import re
H = re.compile(r'^(?P<level>error|warning|note|help)(?:\[(?P<code>[A-Z]\d+)\])?: (?P<message>.*)$')
L = re.compile(r'^\s*-->\s*(?P<file>.+?):(?P<line>\d+):(?P<column>\d+)\s*$')
G = re.compile(r'^\s*(?P<num>\d*)\s*\|(?P<rest>.*)$')
N = re.compile(r'^\s*=\s*(?P<level>note|help|warning): ?(?P<message>.*)$')
MK = re.compile(r'\s*([-^+~]+)(?=\s|$)')
TX = re.compile(r'^[\s|]*')

def parse(lines):
    diags, src, labs, notes = [], [], [], []
    dl, sl, ll, nl, kl = [], [], [], [], []
    summ = {}
    skip = []
    did = 0
    part = 0
    plevel = ''
    last = None
    cur = ''
    pend = {}
    for i, t in enumerate(lines):
        if not t.strip():
            continue
        m = H.match(t)
        if m:
            msg = m.group('message')
            lv = m.group('level')
            if lv == 'error' and msg.startswith('aborting due to'):
                summ['result'] = msg
                kl.append(i)
                continue
            if lv in ('error', 'warning'):
                did += 1
            part += 1
            plevel = lv
            cur = ''
            pend = {}
            last = {'diagnostic': did, 'part': part, 'level': lv, 'code': m.group('code') or '', 'message': msg, 'file': '', 'line': '', 'column': ''}
            diags.append(last)
            dl.append(i)
            continue
        m = L.match(t)
        if m and last is not None:
            last['file'] = m.group('file')
            last['line'] = int(m.group('line'))
            last['column'] = int(m.group('column'))
            dl.append(i)
            continue
        m = N.match(t)
        if m:
            notes.append({'diagnostic': did, 'part': part, 'level': m.group('level'), 'message': m.group('message')})
            nl.append(i)
            continue
        m = G.match(t)
        if m:
            rest = m.group('rest')
            if m.group('num'):
                cur = int(m.group('num'))
                pend = {}
                code = rest[1:] if rest.startswith(' ') else rest
                src.append({'diagnostic': did, 'part': part, 'level': plevel, 'line': cur, 'code': code})
                sl.append(i)
            elif not rest.strip():
                skip.append(i)
            elif not rest.replace('|', '').strip():
                ll.append(i)
            else:
                pos = 0
                marks = []
                while True:
                    mm = MK.match(rest, pos)
                    if not mm:
                        break
                    marks.append((mm.start(1), mm.group(1)))
                    pos = mm.end()
                text = rest[pos:].strip()
                if marks:
                    for k, (c, mk) in enumerate(marks):
                        rec = {'diagnostic': did, 'part': part, 'level': plevel, 'line': cur, 'marker': mk, 'label': text if k == len(marks) - 1 else ''}
                        labs.append(rec)
                        if rec['label']:
                            pend.pop(c, None)
                        else:
                            pend[c] = rec
                else:
                    c = TX.match(rest).end()
                    tx = rest[c:].strip()
                    if c in pend and not pend[c]['label']:
                        pend.pop(c)['label'] = tx
                    else:
                        labs.append({'diagnostic': did, 'part': part, 'level': plevel, 'line': cur, 'marker': '', 'label': tx})
                ll.append(i)
            continue
        m = re.match(r'^Some errors have detailed explanations:\s*(.*?)\.?$', t)
        if m:
            summ['explanations'] = m.group(1)
            kl.append(i)
            continue
        if t.startswith('For more information'):
            summ['more_info'] = t.strip()
            kl.append(i)
            continue
    blocks = []
    if diags:
        blocks.append({'name': 'diagnostics', 'kind': 'table', 'lines': dl, 'records': diags})
    if src:
        blocks.append({'name': 'source_lines', 'kind': 'table', 'lines': sl, 'records': src})
    if labs:
        blocks.append({'name': 'labels', 'kind': 'table', 'lines': ll, 'records': labs})
    if notes:
        blocks.append({'name': 'notes', 'kind': 'table', 'lines': nl, 'records': notes})
    if summ:
        blocks.append({'name': 'summary', 'kind': 'kv', 'lines': kl, 'records': [summ]})
    return {'blocks': blocks, 'skip': skip}
